import{_ as a,o as n,c as i,a3 as c}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-05 — Danh sách phiên đấu giá","description":"","frontmatter":{"title":"SC-05 — Danh sách phiên đấu giá"},"headers":[],"relativePath":"wireframes/public/sc-05-danh-sach-phien.md","filePath":"wireframes/public/sc-05-danh-sach-phien.md","lastUpdated":null}'),l={name:"wireframes/public/sc-05-danh-sach-phien.md"};function t(p,s,e,d,o,h){return n(),i("div",null,[...s[0]||(s[0]=[c('<h1 id="sc-05-—-danh-sach-phien-đau-gia" tabindex="-1">SC-05 — Danh sách phiên đấu giá <a class="header-anchor" href="#sc-05-—-danh-sach-phien-đau-gia" aria-label="Permalink to &quot;SC-05 — Danh sách phiên đấu giá&quot;">​</a></h1><p><span class="wf-badge info">Route: /dau-gia</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-05 · docs/03 UC-03/UC-08 · docs/02 FR-AU-05 · docs/08 BR-AU</span></p><p><strong>Ai xem màn này</strong>: Guest (xem công khai), Thành viên chưa/đã đăng ký phiên, người muốn theo dõi kết quả cũ. Đây là &quot;sảnh chờ&quot; của đấu giá — nơi user quyết định có cọc 90 triệu để tham gia hay không. <strong>Mục đích / cảm xúc thiết kế</strong>: lịch phiên rõ ràng như lịch bay — tab trạng thái, giờ giấc GMT+7, số tiền cọc/bước giá hiện trước khi bấm vào. Không tạo cảm giác &quot;sòng bạc&quot;; LIVE nổi bật nhưng không kích động. <strong>Ví dụ số dùng trong bản vẽ</strong>: phiên <code>DGA-2026-0001</code> căn <code>CT2-A18.05</code> NOXH <code>HP-380</code> · mở giá <code>1.800.000.000 ₫</code> · bước giá <code>18.000.000 ₫</code> (1%) · cọc <code>90.000.000 ₫</code> (5%) · phí 1,5% · countdown <code>00:14:32</code>.</p><h2 id="_1-desktop-—-3-tab-sap-mo-active-card-live-noi-bat" tabindex="-1">1. Desktop — 3 tab (Sắp mở active), card LIVE nổi bật <a class="header-anchor" href="#_1-desktop-—-3-tab-sap-mo-active-card-live-noi-bat" aria-label="Permalink to &quot;1. Desktop — 3 tab (Sắp mở active), card LIVE nổi bật&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/dau-gia?tab=upcoming&amp;page=1</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span class="active">Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NA</span></span></div><div class="wf-container"><div class="wf-row between middle"><span class="wf-title xl">Đấu giá NOXH công khai <span class="wf-callout">1</span></span><span class="wf-small wf-accent">Quy chế đấu giá → SC-08</span></div><div class="wf-tabs" style="margin-top:12px;"><span class="wf-tab active">Sắp mở (4) <span class="wf-callout">2</span></span><span class="wf-tab">Đang diễn ra (1)</span><span class="wf-tab">Kết thúc</span></div><div class="wf-col" style="gap:10px;margin-top:14px;"><div class="wf-card" style="border-color:var(--wf-danger);border-width:2px;"><div class="pad wf-row middle"><div class="wf-img" style="width:130px;min-height:88px;flex:none;"><span>ẢNH CĂN</span></div><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380 <span class="wf-badge danger live">🔴 LIVE</span> <span class="wf-callout">3</span></span><span class="wf-countdown sm">00:14:32</span></span><span class="wf-text">Phiên DGA-2026-0001 · 72 m² · 2 PN · tầng 18 · Sổ hồng</span><div class="wf-row wrap" style="gap:14px;"><span class="wf-small">Giá hiện tại <b class="wf-money">1.926.000.000 ₫</b></span><span class="wf-small">19 lượt · 7 người (ẩn danh)</span></div></div><span class="wf-btn danger">VÀO PHIÊN → SC-06</span></div></div><div class="wf-card"><div class="pad wf-row middle"><div class="wf-img" style="width:130px;min-height:88px;flex:none;"><span>ẢNH CĂN</span></div><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn A2-11.08 — NOXH Tràng Duệ</span><span class="wf-countdown sm">22:14:32 <span class="wf-callout">4</span></span></span><span class="wf-text">Phiên DGA-2026-0002 · 70 m² · 2 PN · tầng 11 · Sổ hồng</span><div class="wf-row wrap" style="gap:14px;"><span class="wf-small">Khởi điểm <b class="wf-money">1.800.000.000 ₫</b></span><span class="wf-small">Bước giá <b class="wf-money">18.000.000 ₫</b></span><span class="wf-small">Cọc <b class="wf-money">90.000.000 ₫</b> <span class="wf-callout">5</span></span></div><span class="wf-small wf-warn-text">Đóng đăng ký: 11/10/2026 14:00 (GMT+7) — còn 1 ngày</span></div><div class="wf-col" style="gap:6px;"><span class="wf-btn primary">Đăng ký tham gia → SC-24</span><span class="wf-btn ghost sm">Xem chi tiết</span></div></div></div><div class="wf-card"><div class="pad wf-row middle"><div class="wf-img" style="width:130px;min-height:88px;flex:none;"><span>ẢNH CĂN</span></div><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn B3-05.01 — NOXH An Đồng</span><span class="wf-countdown sm">46:02:10</span></span><span class="wf-text">Phiên DGA-2026-0003 · 66 m² · 2 PN · tầng 5 · Sổ hồng</span><div class="wf-row wrap" style="gap:14px;"><span class="wf-small">Khởi điểm <b class="wf-money">1.650.000.000 ₫</b></span><span class="wf-small">Bước giá <b class="wf-money">16.500.000 ₫</b></span><span class="wf-small">Cọc <b class="wf-money">82.500.000 ₫</b></span></div><span class="wf-small">Mở: 12/10/2026 09:00 · Đóng đăng ký: 11/10/2026 09:00 (GMT+7)</span></div><div class="wf-col" style="gap:6px;"><span class="wf-btn primary">Đăng ký tham gia → SC-24</span><span class="wf-btn ghost sm">Xem chi tiết</span></div></div></div><span class="wf-small">Card đã qua regDeadline: nút đổi thành disabled + dòng &quot;Đã đóng đăng ký (trước giờ mở 24h)&quot; <span class="wf-callout">6</span></span></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">›</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-05 · docs/03 UC-08 · docs/08 BR-AU)</div><ol><li><span class="num">1</span><span>Dữ liệu `GET /auctions?state=upcoming|live|ended&amp;page=` (🌐 public — endpoint 27). Tab sync vào query `tab=` (shareable như SC-02). Phiên chỉ hiện public khi đã PUBLISHED (notice ≥ 7 ngày trước giờ mở). <span class="ref">FR-AU-05</span> <span class="ref">BR-AU-03</span></span></li><li><span class="num">2</span><span>Đếm mỗi tab lấy từ metadata của 3 request (hoặc 1 request state — BE quyết); mặc định vào trang = tab &quot;Sắp mở&quot;, nếu có phiên LIVE thì <b>tab Đang diễn ra tự nhảy số đếm</b> và card LIVE ghim đầu tab Sắp mở (như bản vẽ) để không ai bỏ lỡ. <span class="ref">docs/05 §3</span></span></li><li><span class="num">3</span><span>Card LIVE: viền đỏ + badge pulse + countdown `hh:mm:ss` đồng bộ `X-Server-Time` (một lần, như SC-06). Hiện &quot;giá hiện tại&quot; thay vì &quot;khởi điểm&quot;; số người tham gia chỉ hiện <b>số lượng</b> — không danh tính (pseudonym chỉ trong feed phiên). <span class="ref">BR-AU-20</span> <span class="ref">BR-AU-21</span></span></li><li><span class="num">4</span><span>Countdown &quot;Sắp mở&quot; = thời gian tới `startAt`, định dạng `hh:mm:ss` khi dưới 24h, thêm ngày khi xa hơn. Về 0 → card tự chuyển LIVE sau poll kế tiếp (list poll 30s ở tab này). <span class="ref">docs/06 conventions</span></span></li><li><span class="num">5</span><span>Card sắp mở <b>luôn hiện đủ 3 số trước khi user quyết định</b>: khởi điểm 1.800.000.000 ₫ · bước giá 18.000.000 ₫ · cọc 90.000.000 ₫ (= 5% khởi điểm, min 10 triệu — công thức BR-AU-06). Không số gộp, không &quot;liên hệ để biết giá&quot;. <span class="ref">BR-AU-06</span> <span class="ref">docs/05 §1.6</span></span></li><li><span class="num">6</span><span>Qua `regDeadline` (= start − 24h): nút &quot;Đăng ký&quot; disabled + message chuẩn 410: &quot;Đã đóng đăng ký (trước giờ mở 24h)&quot;. Vẫn vào xem phiên được (khán giả). &quot;Đăng ký tham gia&quot; → SC-24 (đọc quy chế + cọc); nếu KYC ≠ APPROVED → SC-24 tự chuyển hướng &quot;Đi xác minh&quot;. <span class="ref">BR-AU-04</span> <span class="ref">BR-KYC-08</span> <span class="ref">docs/06 §5</span></span></li></ol></div><h2 id="_2-mobile-360px-—-tabs-cuon-ngang-card-xep-doc" tabindex="-1">2. Mobile 360px — tabs cuộn ngang, card xếp dọc <a class="header-anchor" href="#_2-mobile-360px-—-tabs-cuon-ngang-card-xep-doc" aria-label="Permalink to &quot;2. Mobile 360px — tabs cuộn ngang, card xếp dọc&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-tabs"><span class="wf-tab active">Sắp mở (4)</span><span class="wf-tab">LIVE (1)</span><span class="wf-tab">Kết thúc</span></div><div class="wf-container" style="padding:12px;"><div class="wf-card" style="border-color:var(--wf-danger);border-width:2px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-row between middle"><span class="wf-badge danger live">🔴 LIVE</span><span class="wf-countdown sm">00:14:32</span></span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><div class="wf-row between"><span class="wf-small">Giá hiện tại</span><span class="wf-money">1.926.000.000 ₫</span></div><span class="wf-btn danger block">VÀO PHIÊN → SC-06</span></div></div><div class="wf-card" style="margin-top:10px;"><div class="pad wf-col" style="gap:6px;"><div class="wf-img" style="min-height:100px;"><span>ẢNH CĂN</span></div><span class="wf-title">Căn A2-11.08 — NOXH Tràng Duệ</span><div class="wf-row between"><span class="wf-small">Khởi điểm</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-small">Cọc · bước giá</span><span class="wf-strong">90.000.000 · 18.000.000 ₫</span></div><div class="wf-row between middle"><span class="wf-countdown sm">22:14:32</span><span class="wf-btn primary sm">Đăng ký → SC-24</span></div><span class="wf-small wf-warn-text">Đóng đăng ký 11/10/2026 14:00 (GMT+7)</span></div></div><span class="wf-small">… tab cuộn ngang được; badge LIVE đỏ trên tab khi có phiên đang chạy (kể cả khi đang ở tab khác)</span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Card LIVE luôn ghim đầu danh sách ở <b>mọi tab còn phiên</b>; tap card = vào thẳng SC-06 (không qua trung gian). Countdown + badge giữ nguyên semantics desktop — chỉ đổi layout dọc.</span></li></ol></div><h2 id="_3-tab-ket-thuc-—-card-ket-qua-awarded-failed-cancelled" tabindex="-1">3. Tab &quot;Kết thúc&quot; — card kết quả (AWARDED / FAILED / CANCELLED) <a class="header-anchor" href="#_3-tab-ket-thuc-—-card-ket-qua-awarded-failed-cancelled" aria-label="Permalink to &quot;3. Tab &quot;Kết thúc&quot; — card kết quả (AWARDED / FAILED / CANCELLED)&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:720px;gap:10px;"><span class="wf-state-label">TAB KẾT THÚC — 3 KẾT CỤC</span><div class="wf-card"><div class="pad wf-row middle"><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn D1-03.04 — NOXH Vĩnh Niệm</span><span class="wf-badge ok">ĐÃ TRAO GIẢI</span></span><span class="wf-text">Phiên DGA-2026-0000 · kết thúc 08/10/2026 16:00 (GMT+7) · 24 lượt giá</span><div class="wf-row wrap" style="gap:14px;"><span class="wf-small">Giá trúng <b class="wf-money">1.950.000.000 ₫</b></span><span class="wf-small">bởi <b>TV-K41M</b> <span class="wf-callout">7</span></span></div></div><span class="wf-btn ghost sm">Xem feed → SC-06</span></div></div><div class="wf-card"><div class="pad wf-row middle"><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn A1-02.07 — NOXH An Đồng</span><span class="wf-badge muted">KHÔNG THÀNH</span></span><span class="wf-text">Phiên DGA-2025-0042 · kết thúc 02/10/2026 10:00 · 0 lượt giá</span><span class="wf-small">Căn quay về bán thường — <b class="wf-accent">xem tin SC-03 →</b></span></div><span class="wf-btn ghost sm">Xem tin</span></div></div><div class="wf-card"><div class="pad wf-row middle"><div class="wf-grow wf-col" style="gap:3px;"><span class="wf-row between middle"><span class="wf-title">Căn C2-14.01 — NOXH HP-380</span><span class="wf-badge danger">ĐÃ HỦY</span></span><span class="wf-text">Phiên DGA-2025-0041 · ADMIN hủy trước giờ mở — lý do hiển thị nguyên văn</span><span class="wf-small">Cọc đã hoàn 100% trong 3 ngày làm việc (nếu có người nộp)</span></div><span class="wf-btn ghost sm">Chi tiết</span></div></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">3</span><span class="pg">›</span></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">7</span><span>Card AWARDED hiện <b>giá trúng + pseudonym người trúng</b> (TV-K41M) — không tên thật, đúng chuẩn ẩn danh; feed khóa vẫn xem được (SC-06 §5). FAILED nêu hệ quả thật: căn về bán thường + link tin. CANCELLED hiện lý do (cancel_reason) + cam kết hoàn cọc. <span class="ref">BR-AU-20</span> <span class="ref">BR-AU-13</span> <span class="ref">BR-AU-19</span></span></li><li><span class="num">8</span><span>Tab Kết thúc sort `endedAt desc`; người từng tham gia thấy thêm badge &quot;Bạn đã tham gia&quot; trên card của mình (từ `GET /auctions/{id}/registrations/me`). <span class="ref">docs/06 §3 endpoint 31</span></span></li></ol></div><h2 id="_4-empty-tung-tab-error" tabindex="-1">4. Empty từng tab + Error <a class="header-anchor" href="#_4-empty-tung-tab-error" aria-label="Permalink to &quot;4. Empty từng tab + Error&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">EMPTY — TAB &quot;SẮP MỞ&quot; (không có phiên)</span><div class="wf-empty"><span class="icon">📭</span><span class="wf-title">Chưa có phiên sắp mở</span><br><span class="wf-text">Phiên mới phải công bố trước giờ mở ít nhất 7 ngày. Bật thông báo để không bỏ lỡ phiên kế tiếp.</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Xem các phiên đã kết thúc</span></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — TAB &quot;ĐANG DIỄN RA&quot; (thường xuyên)</span><div class="wf-empty"><span class="icon">⏳</span><span class="wf-title">Không có phiên nào đang diễn ra</span><br><span class="wf-text">Phiên kế tiếp mở lúc 14:00 12/10/2026 (GMT+7) — đăng ký trước giờ mở 24h.</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Về tab Sắp mở</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — GET /auctions thất bại</span><div class="wf-error-box"><span class="wf-title" style="color:var(--wf-danger);">Không tải được danh sách phiên</span><br><span class="wf-small">Đã xảy ra lỗi khi tải dữ liệu. Vui lòng thử lại.</span><br><span class="wf-trace">traceId: 7ab93c01…</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Thử lại</span></div></div></div><div class="wf-col"><span class="wf-state-label">LOADING — skeleton 3 row</span><div class="wf-skeleton"><div class="wf-row middle"><div class="wf-img" style="width:130px;min-height:88px;flex:none;"><span></span></div><div class="wf-lines wf-grow"><span class="w-50"></span><span class="w-90"></span><span class="w-75"></span></div></div></div><div class="wf-skeleton" style="margin-top:8px;"><div class="wf-row middle"><div class="wf-img" style="width:130px;min-height:88px;flex:none;"><span></span></div><div class="wf-lines wf-grow"><span class="w-40"></span><span class="w-75"></span><span class="w-60"></span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">9</span><span>Mỗi tab có empty state <b>riêng theo ngữ cảnh</b> (không dùng chung 1 câu): Sắp mở trống → nhắc quy tắc notice 7 ngày; LIVE trống → trỏ về phiên kế tiếp + deadline đăng ký (start − 24h). Skeleton row cao bằng card thật, không layout-shift. <span class="ref">BR-AU-03/04</span> <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-05" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-05 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-05" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-05&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (card row ngang: ảnh + info + action phải) / tablet 768 / mobile 360 (card dọc, action full-width)</li><li>[ ] 3 tab: Sắp mở / Đang diễn ra / Kết thúc — badge count từng tab, LIVE tab có chấm đỏ khi đang ở tab khác</li><li>[ ] Card sắp mở: countdown tới startAt + đủ 3 số (khởi điểm · bước giá · cọc) + deadline đăng ký warn; biến thể đã đóng đăng ký (disabled + message 410)</li><li>[ ] Card LIVE: viền đỏ + badge pulse + &quot;giá hiện tại&quot; + số lượt/số người (không danh tính)</li><li>[ ] Card kết thúc: 3 kết cục ĐÃ TRAO GIẢI (giá trúng + TV-K41M) / KHÔNG THÀNH (về bán thường) / ĐÃ HỦY (lý do + hoàn cọc)</li><li>[ ] Empty riêng từng tab + Error traceId + Loading skeleton row</li><li>[ ] Copy đúng docs/06 §5 (&quot;Đã đóng đăng ký (trước giờ mở 24h)&quot;); tiền <code>1.800.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> GMT+7</li><li>[ ] Không emoji icon trong UI production (🔴/📭/⏳ là placeholder vị trí)</li><li>[ ] Accessibility: pulse badge không chỉ dựa vào animation (kèm chữ LIVE); countdown có aria-live polite ở chế độ thường (off ở phút cuối — xem SC-06); tab đúng roles ARIA</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd % cọc, notice 7 ngày) cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const w=a(l,[["render",t]]);export{r as __pageData,w as default};
